{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Testosterone, a closely related androstane steroid with the same 4-en-3-one A-ring and no 17α-protective group, has an absolute oral bioavailability of only 3.66 ± 2.45% in women, indicating extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Progesterone, another natural steroid with a 4-en-3-one system, has approximately 5% oral bioavailability due to gut and liver metabolism; the query steroid lacks protective modifications that would avoid this fate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Medroxyprogesterone acetate has low oral bioavailability (<10%) even with a 17α-acetoxy group; the query lacks such metabolic protection, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Testosterone undecanoate, a lipophilic prodrug of testosterone, still has only 6.8 ± 3.3% absolute oral bioavailability; the query is not a prodrug and would be expected to be at least as susceptible to first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Norethisterone has high oral bioavailability (~80%) because of its 17α-ethinyl group, which reduces first-pass metabolism; the query lacks this protective group, so this high-F evidence does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "17-Methyltestosterone has good oral bioavailability due to the 17α-methyl group blocking hepatic metabolism; the query lacks this modification, so the high-F result is not applicable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C49"],
      "claim": "Hydrocortisone has near-complete oral bioavailability, but this is attributable to its corticosteroid dihydroxyacetone side chain and different metabolic profile; the query is an androstenedione-type steroid without these features.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C45"],
      "claim": "A projected 40–70% oral bioavailability for DHEA sulfate is only a projection and involves a 3β-sulfate group, not the 4-hydroxy-4-en-3-one system of the query; it provides weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4-hydroxyandrostenedione-type steroid lacking 17α-alkyl/ethinyl or corticosteroid protective modifications. Directly analogous natural steroids (testosterone, progesterone, medroxyprogesterone acetate, testosterone undecanoate) show low oral bioavailability (<15%) due to extensive first-pass metabolism. High-bioavailability analogues achieve their F through protective groups absent in the query, so the balance of transferable evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself.",
    "No human absolute bioavailability data for 4-hydroxyandrostenedione/formestane in the provided evidence set.",
    "The DHEA sulfate record is a projection rather than a measured absolute bioavailability and has limited structural transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

